CREATE OR REPLACE FUNCTION private.universal_permission_ready(p text)
 RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
 -- Every catalog key is grantable from every source; gates read the shared resolver (has_permission/sig_can/biz_can/k3_can/crm_can/org_can).
 SELECT EXISTS(SELECT 1 FROM public.base_permission_catalog WHERE key=p)
$function$;
CREATE OR REPLACE FUNCTION private.privileged_permission(p text)
 RETURNS boolean LANGUAGE sql IMMUTABLE
AS $function$
 -- Administration keys: grantable to anyone, but only a Super Admin actor may add them (Role editing is already Super-Admin-only).
 SELECT p ~ '^(settings\.|system\.|org\.(manage|assign|appoint)|integration\.)|(\.settings|_settings|_config|access_manage|org_manage|workflow_manage|manage_credentials|manage_settings)$'
$function$;
CREATE OR REPLACE FUNCTION private.universal_permission_scope(p text)
 RETURNS text LANGUAGE sql IMMUTABLE
AS $function$
 -- Label only. Unit data comes solely from the granting position appointment (org_permission_unit_member); other sources give no unit rows.
 SELECT CASE WHEN p LIKE '%\_unit' OR p='biz.crm_view_scope' THEN 'unit' ELSE 'native' END
$function$;
CREATE OR REPLACE FUNCTION private.grant_source_ready(kind text, p text)
 RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
 -- One policy for every Role kind and personal ALLOW; no Role-kind, module or department whitelist. Exceptions are proven scope gaps, not Role-kind whitelists:
 SELECT private.universal_permission_ready(p)
$function$;
